package com.example.transactionrecovery.api;
import com.example.transactionrecovery.domain.Saga; import com.example.transactionrecovery.repository.SagaRepository; import com.example.transactionrecovery.service.*; import com.example.transactionrecovery.tenant.TenantContextResolver; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import org.springframework.web.context.request.NativeWebRequest; import java.util.*;
@RestController @RequestMapping("/api/transaction-demo") public class TransactionDemoController {private final TenantContextResolver tenants;private final ApplicationCommandService commands;private final OutboxPublisher publisher;private final EventDeliveryService delivery;private final SagaRepository sagas;public TransactionDemoController(TenantContextResolver t,ApplicationCommandService c,OutboxPublisher p,EventDeliveryService d,SagaRepository s){tenants=t;commands=c;publisher=p;delivery=d;sagas=s;}
 @PostMapping("/applications") @ResponseStatus(HttpStatus.CREATED) public ApplicationCommandService.Created start(@RequestBody ApplicationCommandService.StartRequest request,NativeWebRequest web){return commands.start(tenants.resolve(web).tenantId(),request);}
 @PostMapping("/outbox/publish") public Map<String,Integer> publish(NativeWebRequest web){tenants.resolve(web);return Map.of("published",publisher.publishPending());}
 @PostMapping("/events/consume") public Map<String,Integer> consume(NativeWebRequest web){tenants.resolve(web);return Map.of("consumed",delivery.consumeAvailable());}
 @GetMapping("/sagas/{id}") public Saga saga(@PathVariable UUID id,NativeWebRequest web){String tenant=tenants.resolve(web).tenantId();return sagas.findByIdAndTenantId(id,tenant).orElseThrow(()->new NoSuchElementException("Saga not found"));}
}
